SELECT l.id AS id, l.shelf_id AS shelfId, s.shelf_no AS shelfNo, s.area AS area, l.location_no AS locationNo, l.row_no AS rowNo, l.column_no AS columnNo, l.capacity AS capacity, l.used_count AS usedCount, l.status AS status, DATE_FORMAT(l.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, DATE_FORMAT(l.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime FROM shelf_location l JOIN shelf s ON s.id = l.shelf_id AND s.deleted = 0
AND l.shelf_id = #{shelfId}
AND l.status = #{status}
ORDER BY l.shelf_id ASC, l.row_no ASC, l.column_no ASC

SELECT l.id AS id, l.shelf_id AS shelfId, s.shelf_no AS shelfNo, s.area AS area, l.location_no AS locationNo, l.row_no AS rowNo, l.column_no AS columnNo, l.capacity AS capacity, l.used_count AS usedCount, l.status AS status, DATE_FORMAT(l.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, DATE_FORMAT(l.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime FROM shelf_location l JOIN shelf s ON s.id = l.shelf_id AND s.deleted = 0 AND s.status = 1 WHERE l.status != 4 AND l.used_count < l.capacity
AND l.shelf_id = #{shelfId}
ORDER BY l.shelf_id ASC, l.row_no ASC, l.column_no ASC

SELECT COUNT(*) AS count
FROM shelf_location
WHERE location_no = #{locationNo}

    AND id != #{excludeId}

SELECT COUNT(*) AS count
FROM shelf_location
WHERE shelf_id = #{shelfId}
  AND row_no = #{rowNo}
  AND column_no = #{columnNo}

    AND id != #{excludeId}

mapper.update:
UPDATE shelf_location
SET status = #{status},
    update_time = #{updateTime}
WHERE id = #{id}
